SINA_SMART["toxico-kinetics"] = {"lecture":"toxico-kinetics","title":"Toxicokinetics","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"toxico-kinetics:e0","text":"ADME: absorption, distribution, metabolism, excretion.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"toxico-kinetics:e1","text":"Passive diffusion is the main mechanism (Fick's law).","topic":"Crossing membranes and absorption","sec":1,"importance":"core","highYield":"untested"},{"id":"toxico-kinetics:e2","text":"Facilitated diffusion and active transport are saturable; active uses ATP.","topic":"Crossing membranes and absorption","sec":1,"importance":"core","highYield":"untested"},{"id":"toxico-kinetics:e3","text":"P-glycoprotein is an ABC efflux pump, key at the BBB.","topic":"Crossing membranes and absorption","sec":1,"importance":"core","highYield":"untested"},{"id":"toxico-kinetics:e4","text":"F = AUC oral / AUC IV.","topic":"Crossing membranes and absorption","sec":1,"importance":"core","highYield":"untested"},{"id":"toxico-kinetics:e5","text":"Only un-ionised, lipophilic forms cross membranes.","topic":"Crossing membranes and absorption","sec":1,"importance":"core","highYield":"untested"},{"id":"toxico-kinetics:e6","text":"Protein binding lowers immediate toxicity but prolongs intoxication.","topic":"Distribution","sec":2,"importance":"core","highYield":"untested"},{"id":"toxico-kinetics:e7","text":"Weak bases are trapped in cells (ion trapping).","topic":"Distribution","sec":2,"importance":"core","highYield":"untested"},{"id":"toxico-kinetics:e8","text":"Paracetamol → NAPQI (phase I), neutralised by glutathione (phase II).","topic":"Metabolism","sec":3,"importance":"core","highYield":"untested"},{"id":"toxico-kinetics:e9","text":"Inducers: smoking, alcohol, rifampicin; inhibitors: grapefruit, ketoconazole.","topic":"Metabolism","sec":3,"importance":"core","highYield":"untested"},{"id":"toxico-kinetics:e10","text":"Alkaline urine increases excretion of weak acids (salicylates).","topic":"Excretion and kinetic parameters","sec":4,"importance":"core","highYield":"untested"},{"id":"toxico-kinetics:e11","text":"t½ = 0.693 × Vd / CL; steady state after 4-5 half-lives.","topic":"Excretion and kinetic parameters","sec":4,"importance":"core","highYield":"untested"},{"id":"toxico-kinetics:e12","text":"Zero-order: alcohol, high-dose aspirin.","topic":"Excretion and kinetic parameters","sec":4,"importance":"core","highYield":"untested"},{"id":"toxico-kinetics:e13","text":"Post-mortem: sample femoral blood and vitreous humour, not cardiac blood.","topic":"Post-mortem redistribution","sec":5,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"xuv4xh":"a","1x0x678":"a","18gugfm":"a","2pfj2":"a","hw0xhv":"a","1nvvnvi":"a","1ffptki":"a","1lkh14d":"a","1s0mla4":"a","1z0iy7":"a","emg9yu":"a","1tdmz6q":"a","zs8jp2":"a","nwqs2a":"a","kl2csd":"a","12bmvwi":"a","1injnwi":"a","jowlmr":"a","h9rgxe":"x","1c7hgtb":"x"},"mapCounts":{"verified":0,"auto":18,"ambiguous":0,"missing":2},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"toxico-kinetics:e0":{"s":0,"u":["ADME: absorption, distribution, metabolism, excretion.","Toxicokinetics is what the body does to a toxicant: its absorption, distribution, metabolism and excretion (ADME) , the effect of patient and disease factors, and their mathematical description."],"dp":[]},"toxico-kinetics:e1":{"s":1,"u":["Passive diffusion is the main mechanism (Fick's law).","Mechanisms : passive diffusion (main route; no carrier, no ATP, down the gradient; Fick's law : rate ∝ area × concentration difference / thickness); facilitated diffusion (carrier, no energy, saturable, competitive; glucose, amino acids); active transport (carrier + ATP, against the gradient, selective, saturable); filtration through pores (under 4 nm in the gut, e.g. methanol; about 70 nm in glomeruli); endocytosis (pinocytosis of dyes; alveolar macrophages phagocytose asbestos)."],"dp":[]},"toxico-kinetics:e2":{"s":1,"u":["Facilitated diffusion and active transport are saturable; active uses ATP.","Mechanisms : passive diffusion (main route; no carrier, no ATP, down the gradient; Fick's law : rate ∝ area × concentration difference / thickness); facilitated diffusion (carrier, no energy, saturable, competitive; glucose, amino acids); active transport (carrier + ATP, against the gradient, selective, saturable); filtration through pores (under 4 nm in the gut, e.g. methanol; about 70 nm in glomeruli); endocytosis (pinocytosis of dyes; alveolar macrophages phagocytose asbestos)."],"dp":[]},"toxico-kinetics:e3":{"s":1,"u":["P-glycoprotein is an ABC efflux pump, key at the BBB.","Transporters : influx SLC (OATP into liver, OCT with renal accumulation and nephrotoxicity, PEPT); efflux ABC ( P-glycoprotein , key at the blood-brain barrier; BCRP; MRP)."],"dp":[]},"toxico-kinetics:e4":{"s":1,"u":["F = AUC oral / AUC IV.","Bioavailability F = fraction absorbed × fraction escaping first-pass = AUC oral / AUC IV (IV = 100%)."],"dp":[]},"toxico-kinetics:e5":{"s":1,"u":["Only un-ionised, lipophilic forms cross membranes.","Oral : only the un-ionised, lipophilic form crosses; acids are less ionised at low pH, bases at high pH."],"dp":[]},"toxico-kinetics:e6":{"s":2,"u":["Protein binding lowers immediate toxicity but prolongs intoxication.","Protein binding keeps the absorption gradient high, reduces glomerular filtration and hepatic metabolism: it reduces immediate toxicity but prolongs intoxication ."],"dp":[]},"toxico-kinetics:e7":{"s":2,"u":["Weak bases are trapped in cells (ion trapping).","Only the free, non-ionised form diffuses; cells are more acidic (pH 6.9) than plasma (7.4), so weak bases are trapped inside cells (ion trapping) ."],"dp":[]},"toxico-kinetics:e8":{"s":3,"u":["Paracetamol → NAPQI (phase I), neutralised by glutathione (phase II).","Some phase I products are more toxic : paracetamol → NAPQI .","Phase II (conjugation) : glucuronidation (morphine), sulfation (paracetamol), acetylation (isoniazid, sulphonamides, hydralazine, procainamide; may make aromatic amines carcinogenic), glutathione conjugation (neutralises NAPQI)."],"dp":[]},"toxico-kinetics:e9":{"s":3,"u":["Inducers: smoking, alcohol, rifampicin; inhibitors: grapefruit, ketoconazole.","Modifiers : genetics (fast vs slow acetylators), age (neonates, elderly), sex, liver disease, inducers (smoking, alcohol, rifampicin) and inhibitors (grapefruit juice, ketoconazole)."],"dp":[]},"toxico-kinetics:e10":{"s":4,"u":["Alkaline urine increases excretion of weak acids (salicylates).","Renal : glomerular filtration (small, unbound), active tubular secretion, passive reabsorption depending on urine pH (acid urine keeps weak acids; alkalinising urine increases excretion of weak acids such as salicylates )."],"dp":[{"h":"Why alkalinising the urine helps in aspirin poisoning","t":"Salicylic acid is a weak acid. In alkaline urine most of it is ionised, and ionised molecules cannot diffuse back through the tubular wall. It is therefore trapped in the urine and excreted, instead of being reabsorbed. This is ion trapping used as a treatment. Source: the lecture's tubular reabsorption slide."}]},"toxico-kinetics:e11":{"s":4,"u":["t½ = 0.693 × Vd / CL; steady state after 4-5 half-lives.","Steady state after 4 to 5 half-lives .","Half-life : time for plasma concentration to halve; t½ = ln2 / K = 0.693 × Vd / CL ."],"dp":[]},"toxico-kinetics:e12":{"s":4,"u":["Zero-order: alcohol, high-dose aspirin.","Zero-order : constant amount removed (alcohol, high-dose aspirin), with accumulation risk.","First-order kinetics: constant fraction removed (most drugs)."],"dp":[]},"toxico-kinetics:e13":{"s":5,"u":["Post-mortem: sample femoral blood and vitreous humour, not cardiac blood.","Cardiac blood overestimates ante-mortem levels; use femoral (peripheral) blood , compare with vitreous humour (resistant to PMR) and liver, consider the post-mortem interval and the case context.","After death, drugs move between compartments: passive diffusion from drug-rich organs (liver, lungs, heart) into central blood, release from fat stores, cadaveric blood movement, and bacterial or enzymatic activity (degradation, or post-mortem ethanol production )."],"dp":[{"h":"Why cardiac blood misleads after death","t":"Lipophilic drugs with a large volume of distribution are concentrated in the lungs, liver and heart muscle. After death, circulation stops and they diffuse back into the nearby blood, so blood drawn from the heart can show several times the level present in life. Peripheral femoral blood, far from these reservoirs, stays closer to the true value, which is why the lecture's cases were reclassified from overdose to therapeutic use. Source: the lecture's post-mortem redistribution cases."}]}},"meta":{"xuv4xh":{"a":"relationship","vg":"toxico-kinetics:e1/relationship/1"},"1x0x678":{"a":"recall","vg":"toxico-kinetics:e1/recall/1"},"18gugfm":{"a":"recall","vg":"toxico-kinetics:e2/recall/1"},"2pfj2":{"a":"recall","vg":"toxico-kinetics:e3/recall/1"},"hw0xhv":{"a":"recall","vg":"toxico-kinetics:e4/recall/1"},"1nvvnvi":{"a":"recall","vg":"toxico-kinetics:e5/recall/1"},"1ffptki":{"a":"recall","vg":"toxico-kinetics:e6/recall/1"},"1lkh14d":{"a":"recall","vg":"toxico-kinetics:e7/recall/1"},"1s0mla4":{"a":"recall","vg":"toxico-kinetics:e0/recall/1"},"1z0iy7":{"a":"recall","vg":"toxico-kinetics:e8/recall/1"},"emg9yu":{"a":"recall","vg":"toxico-kinetics:e8/recall/2"},"1tdmz6q":{"a":"recall","vg":"toxico-kinetics:e9/recall/1"},"zs8jp2":{"a":"recall","vg":"toxico-kinetics:e10/recall/1"},"nwqs2a":{"a":"recall","vg":"toxico-kinetics:e11/recall/1"},"kl2csd":{"a":"relationship","vg":"toxico-kinetics:e12/relationship/1"},"12bmvwi":{"a":"recall","vg":"toxico-kinetics:e11/recall/2"},"1injnwi":{"a":"recall","vg":"toxico-kinetics:e13/recall/1"},"jowlmr":{"a":"relationship","vg":"toxico-kinetics:e13/relationship/1"}},"explRev":"4431c0f20fdf"};
